"""Read-only matched forecasting figure."""
HTML="<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Compute Forecast · Market context</title><style>\n@font-face{font-family:Note;src:url('/assets/note.ttf')}*{box-sizing:border-box}body{margin:0;background:#f7f3e8;color:#202b36;font:15px/1.55 system-ui,sans-serif}main{max-width:1260px;margin:auto;padding:32px 38px}nav{display:flex;gap:24px;align-items:center;border-bottom:1px solid #d8d3c5;padding-bottom:15px}a{color:#244db7;text-underline-offset:4px}nav a{font-size:13px}h1{font:500 clamp(30px,4.2vw,53px)/1.12 Georgia,serif;max-width:850px;margin:36px 0 13px}h2{font:500 26px Georgia,serif;margin:22px 0 12px}p{max-width:850px}.eyebrow{letter-spacing:.13em;text-transform:uppercase;font-size:11px;color:#53616c}.note{font:24px Note,cursive;color:#3d6559}.muted{color:#59636b}.controls{display:flex;flex-wrap:wrap;gap:14px;align-items:end;margin:22px 0 8px}label{display:grid;font-size:12px;gap:5px}button,select{font:inherit;color:inherit;border:1px solid #aaa99f;background:#fffcf5;border-radius:5px;padding:8px 12px}button{cursor:pointer}button:hover{border-color:#234fb8}button:focus-visible,select:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #2c5dc1;outline-offset:3px}.legend{display:flex;flex-wrap:wrap;gap:20px;font-size:12px}.key:before{content:'';display:inline-block;width:22px;border-top:2px solid var(--c);vertical-align:middle;margin-right:7px}.figure{margin:20px 0;border-top:1px solid #d8d3c5;border-bottom:1px solid #d8d3c5;padding:12px 0 20px}.figure svg{display:block;width:100%;height:auto;touch-action:pan-y;overflow:visible}.grid{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:28px}.margin{border-left:1px solid #d8d3c5;padding-left:20px}.readout{font-variant-numeric:tabular-nums;white-space:pre-line;font-size:13px}.stats{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}.stats th,.stats td{text-align:right;padding:10px;border-bottom:1px solid #ded9ce;font-size:13px}.stats th:first-child,.stats td:first-child{text-align:left}.status{padding:18px 0;color:#4b5964}.error{color:#8c312c}.figure circle:focus-visible{outline:2px solid #b18124;outline-offset:3px}.pill{font:11px system-ui;border:1px solid #c8c1b2;border-radius:20px;padding:4px 9px}.small{font-size:12px}details{padding:15px 0;border-bottom:1px solid #ded9ce}summary{cursor:pointer}footer{margin-top:35px;font-size:12px;color:#5b6470}.pins{display:grid;gap:9px}.pin{padding:10px;background:#fffcf3;border-left:2px solid #244db7;overflow-wrap:anywhere}.two{display:grid;grid-template-columns:1fr 1fr;gap:28px}\n@media(max-width:700px){main{padding:20px 16px}nav{gap:15px;flex-wrap:wrap}.grid,.two{grid-template-columns:1fr}.margin{border-left:0;border-top:1px solid #d8d3c5;padding:15px 0 0}.controls label:first-child{width:100%}select{max-width:100%;min-width:0}.stats th,.stats td{font-size:11px;padding:7px 3px}h1{margin-top:26px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}\n</style><main><nav><strong>COMPUTE FORECAST</strong><a href=\"/probability\">Direct forecasting</a><a href=\"/market\">Market context</a><a href=\"https://github.com/howdymary/mochi-demo/blob/compute-observatory/docs/market-state-v19.md\">Methods & sources</a></nav>\n<h1>Can other providers’ prices help us forecast the next move?</h1><p class=\"muted\">The same forecasting model, trained twice: with its own price history, and with added market-price context. New information has to earn its place.</p><span class=\"pill\">v19 · separate registered study</span> <span class=\"pill\">Prospective accuracy pending</span>\n<div id=\"status\" class=\"status\" role=\"status\">Loading verified research artifacts…</div><button id=\"retry\" hidden>Retry</button> <button id=\"refresh\">Refresh artifacts</button>\n<section id=\"results\" hidden><div class=\"controls\"><label>Historical development case<select id=\"case\"></select></label><label>Training seed<select id=\"seed\"><option>17</option><option>29</option><option>43</option></select></label><label>Optimizer update<select id=\"checkpoint\"></select></label></div>\n<div class=\"legend\"><span class=\"key\" style=\"--c:#475360\">Observed history</span><span class=\"key\" style=\"--c:#2456be\">Price history only</span><span class=\"key\" style=\"--c:#16705e\">With market context</span><span class=\"key\" style=\"--c:#b18124\">Archived outcomes</span></div>\n<div class=\"figure\"><div class=\"grid\"><div><svg id=\"price\" viewBox=\"0 0 870 400\" role=\"img\" aria-label=\"Historical price and actual checkpoint forecasts\"></svg><div class=\"small muted\">USD per GPU-hour · dots are measured 1-, 3- and 7-day forecasts; dashed connections are visual guides. Shading joins q10–q90 points.</div></div><aside class=\"margin\"><div class=\"eyebrow\">At the forecast origin</div><p class=\"note\" id=\"annotation\"></p><div id=\"point\" class=\"readout\" aria-live=\"polite\"></div><label>Inspect forecast horizon<select id=\"horizon\"><option value=\"1\">1 day</option><option value=\"3\">3 days</option><option value=\"7\" selected>7 days</option></select></label><p><button id=\"pin\">Pin this observation</button></p></aside></div></div>\n<h2>What changed during training?</h2><p class=\"small muted\">Development seven-day quantile pinball loss. Lower is better. All saved checkpoints are shown; a ring marks each run’s original selected checkpoint. This is model selection, not a future-accuracy result.</p><svg id=\"learning\" viewBox=\"0 0 1100 250\" role=\"img\" aria-label=\"Six matched development checkpoint trajectories\" style=\"width:100%;height:auto\"></svg>\n<h2>The matched retrospective comparison</h2><p id=\"scope\" class=\"small muted\"></p><table class=\"stats\"><thead><tr><th>Condition / control</th><th>7-day pinball ↓</th><th>Coverage</th><th>Interval width</th></tr></thead><tbody id=\"scores\"></tbody></table><p class=\"small muted\">Coverage and width are shown together; the nominal q10–q90 coverage is 80%. Seed averages reuse the same outcomes.</p>\n<details><summary>Median accuracy, failures and denominators</summary><div id=\"diagnostics\" class=\"readout\"></div></details><details><summary>Research decisions and their consequences</summary><div id=\"ledger\"></div></details><details><summary>Evidence available to the model</summary><div id=\"evidence\" class=\"readout\"></div></details><details><summary>Pinned observations</summary><div id=\"pins\" class=\"pins\"></div><button id=\"clear\">Clear pins</button></details>\n</section><section><h2>The future test</h2><div id=\"future\" class=\"status\">Loading the separate panel’s status…</div><p class=\"small muted\">A new individual-provider contract cohort. It is separate from the archived competition targets and the existing December 6 panel. No curve is drawn through pending outcomes.</p></section>\n<details><summary>What this experiment can establish</summary><p>Historical comparisons use source-reported snapshot timestamps and reused, dependent dates. The new inputs describe observed collector composition and other providers’ changes within their own stable source-defined groups. They do not measure GPU utilization, market-wide demand, or guaranteed availability.</p><p>News, availability, BLS and infrastructure are excluded from this training comparison. Cross-provider dollar comparisons require matching recorded region and node details; those ratios were unavailable in the historical training cohort.</p><p><a href=\"https://github.com/howdymary/mochi-demo/tree/compute-observatory/results/market-state-v19\">Versioned artifacts</a> · <a href=\"https://github.com/howdymary/mochi-demo/blob/compute-observatory/docs/market-state-v19.md\">Reproduction and study design</a></p></details><footer>Pacific Machines (2026), gpu-price-pack v0.1.1-handover, CC BY 4.0 compilation; GPU Price Tracker component, CC BY 4.0. Continuing quotes: GPU Rental Prices, CC BY 4.0. <span id=\"identity\"></span></footer></main>\n<script>\nconst $=x=>document.getElementById(x), NS='http://www.w3.org/2000/svg';let report,selectedCase;const colors={price:'#2456be',market:'#16705e'}, saved=JSON.parse(sessionStorage.getItem('market-v19-selection')||'{}');let pins=JSON.parse(localStorage.getItem('market-v19-pins')||'[]');\nfunction node(tag,attrs={},text){const n=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));if(text!==undefined)n.textContent=text;return n}function add(svg,tag,attrs,text){const n=node(tag,attrs,text);svg.append(n);return n}function num(x){return x==null?'—':Number(x).toFixed(5)}function line(points){return points.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ')}function text(svg,x,y,s,attrs={}){add(svg,'text',{x,y,fill:'#53616c','font-size':12,'font-family':'system-ui',...attrs},s)}\nfunction axes(svg,w,h,domain,range,xformatter){const [l,r,t,b]=[58,w-25,24,h-40],x=v=>l+(v-domain[0])/(domain[1]-domain[0])*(r-l),y=v=>b-(v-range[0])/(range[1]-range[0])*(b-t);for(let i=0;i<5;i++){let v=range[0]+i*(range[1]-range[0])/4;add(svg,'line',{x1:l,x2:r,y1:y(v),y2:y(v),stroke:'#dcd8cd','stroke-width':.7});text(svg,l-9,y(v)+4,num(v),{'text-anchor':'end'})}for(let i=0;i<5;i++){let v=domain[0]+i*(domain[1]-domain[0])/4;text(svg,x(v),h-12,xformatter(v),{'text-anchor':'middle'})}return {x,y,l,r,t,b}}\nfunction checkpoints(){const seed=+$('seed').value;return [...new Set(report.runs.filter(r=>r.seed===seed).flatMap(r=>r.checkpoints.map(c=>c.update)))].sort((a,b)=>a-b)}\nfunction options(){const old=$('checkpoint').value;const cps=checkpoints();$('checkpoint').replaceChildren(...cps.map(v=>new Option(v===0?'0 · untuned':String(v),v)));$('checkpoint').value=cps.includes(+old)?old:String(cps[0])}\nfunction draw(){selectedCase=report.cases[+$('case').value];const c=selectedCase,seed=+$('seed').value,update=+$('checkpoint').value,horizon=+$('horizon').value, groups=c.checkpoints.filter(r=>r.seed===seed), svg=$('price');svg.replaceChildren();const width=Math.max(350,Math.round(svg.getBoundingClientRect().width));svg.setAttribute('viewBox','0 0 '+width+' 400');const day=s=>Date.parse(s+'T00:00:00Z')/86400000, origin=day(c.origin);const vals=[...c.history.map(r=>r.value),...c.outcomes,...c.checkpoints.flatMap(g=>g.rows.flatMap(r=>[r.q10,r.q90]))];let lo=Math.min(...vals),hi=Math.max(...vals),pad=Math.max((hi-lo)*.13,hi*.025);const {x,y,t,b}=axes(svg,width,400,[day(c.history[0].date),origin+8],[Math.max(0,lo-pad),hi+pad],d=>new Date(d*86400000).toISOString().slice(5,10));let segment=[];for(let i=0;i<c.history.length;i++){let r=c.history[i];if(i&&day(r.date)-day(c.history[i-1].date)>1){add(svg,'path',{d:line(segment),fill:'none',stroke:'#475360','stroke-width':2});segment=[]}segment.push([x(day(r.date)),y(r.value)])}add(svg,'path',{d:line(segment),fill:'none',stroke:'#475360','stroke-width':2});for(const r of c.history){const dot=add(svg,'circle',{cx:x(day(r.date)),cy:y(r.value),r:3,fill:'#475360',stroke:'transparent','stroke-width':16,tabindex:0,role:'button','aria-label':'Inspect historical price '+r.date});const inspect=()=>{$('point').textContent='Historical observation\\n'+r.date+' · '+num(r.value)+' USD per GPU-hour\\nSource: '+c.metadata.source_id+'\\nProvider: '+c.metadata.provider+'\\nSource snapshot: '+(r.available_at||'Unverified')+'\\n'+c.metadata.benchmark_contract};dot.onmouseenter=inspect;dot.onfocus=inspect;dot.onclick=inspect;dot.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspect()}}}add(svg,'line',{x1:x(origin),x2:x(origin),y1:t,y2:b,stroke:'#999789','stroke-dasharray':'3 4'});text(svg,x(origin)-8,t+8,'Origin '+c.origin,{'text-anchor':'end'});\nfor(const arm of ['price','market']){let g=groups.find(g=>g.arm===arm&&g.update===update);if(!g)continue;let rows=[...g.rows].sort((a,b)=>a.horizon_days-b.horizon_days);let band=[...rows.map(r=>[x(origin+r.horizon_days),y(r.q10)]),...rows.slice().reverse().map(r=>[x(origin+r.horizon_days),y(r.q90)])];add(svg,'path',{d:line(band)+'Z',fill:colors[arm],opacity:.11});add(svg,'path',{d:line(rows.map(r=>[x(origin+r.horizon_days),y(r.q50)])),fill:'none',stroke:colors[arm],'stroke-width':2.3,'stroke-dasharray':'5 4'});for(const r of rows){const dot=add(svg,'circle',{cx:x(origin+r.horizon_days),cy:y(r.q50),r:4,fill:colors[arm],stroke:'transparent','stroke-width':14,tabindex:0,role:'button','aria-label':'Inspect '+arm+' forecast '+r.horizon_days+' days'});const inspect=()=>{$('point').textContent=(arm==='price'?'Price only':'Market context')+' · update '+update+'\\n'+r.target_date+'\\nq10 / q50 / q90: '+[r.q10,r.q50,r.q90].map(num).join(' / ')+' USD per GPU-hour\\nCase pinball: '+num(r.loss)+'\\nArtifact '+report.public_report_sha256};dot.onmouseenter=inspect;dot.onfocus=inspect;dot.onclick=inspect;dot.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspect()}}}}\nc.target_dates.forEach((d,i)=>add(svg,'circle',{cx:x(day(d)),cy:y(c.outcomes[i]),r:4,fill:'#b18124',stroke:'#fffaf0','stroke-width':1}));let ix=[1,3,7].indexOf(horizon);add(svg,'line',{x1:x(origin+horizon),x2:x(origin+horizon),y1:t,y2:b,stroke:'#b18124',opacity:.4});$('annotation').textContent=c.metadata.provider+' · '+c.metadata.gpu_model;$('point').textContent=c.origin+' → '+c.target_dates[ix]+'\\nUSD per GPU-hour\\n'+['price','market'].map(arm=>{let g=groups.find(g=>g.arm===arm&&g.update===update),r=g?.rows.find(r=>r.horizon_days===horizon);if(!r)return (arm==='price'?'Price only':'Market context')+': checkpoint pending';return (arm==='price'?'Price only':'Market context')+': '+num(r?.q50)+'\\nq10–q90: '+num(r?.q10)+' – '+num(r?.q90)+'\\nCase pinball: '+num(r?.loss)}).join('\\n\\n')+'\\n\\nArchived outcome: '+num(c.outcomes[ix]);$('evidence').textContent=Object.entries(c.market_state).map(([k,v])=>k+': '+(v==null?'Unavailable':num(v))).join('\\n')+'\\n\\nInput identity: '+c.market_input_identity;\ndrawLearning(update);sessionStorage.setItem('market-v19-selection',JSON.stringify({case:$('case').value,seed:$('seed').value,checkpoint:$('checkpoint').value,horizon:$('horizon').value}))}\nfunction drawLearning(update){const svg=$('learning');svg.replaceChildren();const width=Math.max(350,Math.round(svg.getBoundingClientRect().width));svg.setAttribute('viewBox','0 0 '+width+' 250');const all=report.runs.flatMap(r=>r.checkpoints.map(c=>c.development.primary_pinball)),lo=Math.min(...all),hi=Math.max(...all),pad=Math.max((hi-lo)*.12,.001),max=Math.max(...report.runs.map(r=>r.optimizer_updates));const {x,y,t,b}=axes(svg,width,250,[0,max],[Math.max(0,lo-pad),hi+pad],v=>Math.round(v));add(svg,'line',{x1:x(update),x2:x(update),y1:t,y2:b,stroke:'#a49e91','stroke-dasharray':'3 4'});report.runs.forEach(r=>{const active=r.seed===+$('seed').value;let rows=r.checkpoints;add(svg,'path',{d:line(rows.map(c=>[x(c.update),y(c.development.primary_pinball)])),fill:'none',stroke:colors[r.arm],'stroke-width':active?2.5:1.3,opacity:active?1:.35,'stroke-dasharray':r.seed===29?'6 4':r.seed===43?'2 4':''});rows.forEach(c=>{add(svg,'circle',{cx:x(c.update),cy:y(c.development.primary_pinball),r:c.update===r.selected?.update?5:2.8,fill:c.update===r.selected?.update?'#f7f3e8':colors[r.arm],stroke:colors[r.arm],'stroke-width':1.8})})});text(svg,58,14,width<600?'Seeds 17 / 29 / 43':'SEEDS 17 / 29 / 43 · solid / dashed / dotted');text(svg,width-25,14,width<600?'Updates':'Actual optimizer updates',{'text-anchor':'end'})}\nfunction table(){const groups=[];for(const arm of ['price','market']){let rs=report.runs.filter(r=>r.arm===arm&&r.retrospective),r=rs.map(r=>r.retrospective.summary.by_horizon['7']);if(r.length)groups.push([(arm==='price'?'Price-only':'Market context')+' · '+r.length+' completed seeds',{pinball:r.reduce((a,b)=>a+b.pinball,0)/r.length,coverage:r.reduce((a,b)=>a+b.coverage,0)/r.length,width:r.reduce((a,b)=>a+b.width,0)/r.length}]);const base=report.runs.find(r=>r.arm===arm)?.untuned?.summary?.by_horizon['7'];if(base)groups.push(['Untuned · '+arm,base])}for(const [name,r] of Object.entries(report.controls.results.retrospective))groups.push([name,r.summary.by_horizon['7']]);$('scores').replaceChildren(...groups.map(([name,s])=>{let tr=document.createElement('tr');[name,num(s.pinball),(s.coverage*100).toFixed(1)+'%',num(s.width)].forEach(v=>{let td=document.createElement('td');td.textContent=v;tr.append(td)});return tr}));$('diagnostics').textContent=report.runs.filter(r=>r.retrospective).map(r=>{let s=r.retrospective.summary.by_horizon['7'];return r.arm+' · seed '+r.seed+' · n='+s.n+' · median MAE '+num(s.median_mae)+' · failures '+s.failures}).join('\\n')||'Trained-model retrospective results are pending.';const a=report.audit.phases.retrospective;$('scope').textContent=a.windows+' seven-day cases · '+a.contracts+' source-defined groups · '+a.origins.length+' reused, dependent dates. Historical comparison; no future-performance conclusion.'}\nfunction renderPins(){$('pins').replaceChildren(...pins.map(p=>{let el=document.createElement('div');el.className='pin';el.textContent=p.text+'\\nArtifact '+p.artifact.slice(0,16)+' · update '+p.update;return el}))}\n$('pin').onclick=()=>{pins.push({artifact:report.public_report_sha256,case:selectedCase.task_id,seed:$('seed').value,update:$('checkpoint').value,text:$('point').textContent});pins=pins.slice(-12);localStorage.setItem('market-v19-pins',JSON.stringify(pins));renderPins()};$('clear').onclick=()=>{pins=[];localStorage.removeItem('market-v19-pins');renderPins()};['case','checkpoint','horizon'].forEach(id=>$(id).onchange=draw);$('seed').onchange=()=>{options();draw()};\nasync function load(){try{Object.assign(saved,JSON.parse(sessionStorage.getItem('market-v19-selection')||'{}'));$('status').textContent='Loading verified research artifacts…';const r=await fetch('/api/market-v19');if(!r.ok)throw Error('Research publication unavailable ('+r.status+')');report=await r.json();if(!report.runs?.length)throw Error('The registered campaign is pending; no checkpoint results are published yet.');$('case').replaceChildren(...report.cases.map((c,i)=>new Option(c.metadata.provider+' · '+c.metadata.gpu_model+' · '+c.origin,i)));if(saved.case)$('case').value=saved.case;if(saved.seed)$('seed').value=saved.seed;options();if(saved.checkpoint&&checkpoints().includes(+saved.checkpoint))$('checkpoint').value=saved.checkpoint;if(saved.horizon)$('horizon').value=saved.horizon;table();draw();renderPins();$('ledger').replaceChildren(...(report.iteration_ledger||[]).map(entry=>{let box=document.createElement('p');box.textContent=entry.id+' · '+entry.status+'\\n'+entry.hypothesis+'\\nDecision: '+entry.decision;return box}));$('results').hidden=false;$('status').textContent=report.status==='training_in_progress'?'Training in progress · at least '+report.new_optimizer_updates+' updates retained · '+report.completed_runs+' / 6 runs complete':report.new_optimizer_updates+' actual optimizer updates · six matched runs · source-verified public artifacts';$('identity').textContent='Report '+report.public_report_sha256?.slice(0,16);$('retry').hidden=true}catch(e){$('status').textContent=e.message;$('status').classList.add('error');$('retry').hidden=false}}$('retry').onclick=load;$('refresh').onclick=load;\nasync function future(){try{let r=await fetch('/api/market-v19/future');if(!r.ok)throw Error('Future panel status unavailable');let x=await r.json();$('future').textContent=(x.issued_origins||0)+' origins issued. Earliest origin: '+(x.first_eligible_origin||'2026-12-20')+'. Final analysis: '+(x.final_analysis_not_before||'2027-04-12').slice(0,10)+'.\\n'+(x.reasons||[]).join(' · ')+'. Prospective improvement is not yet established.'}catch(e){$('future').textContent=e.message+'. Forecast outcomes remain pending.'}}let timer;window.addEventListener('resize',()=>{clearTimeout(timer);timer=setTimeout(()=>{if(report?.runs?.length)draw()},120)});load();future();\n</script></html>"
